const fs = require('fs');
const repo = $env.AGENT_REPO_PATH || '/data/repo';
const input = $input.item.json;
const agentId = input.agentId;
if (!agentId) { throw new Error('agentId が指定されていません'); }
const dir = `${repo}/agents/${agentId}`;
const system = fs.readFileSync(`${dir}/prompt.md`, 'utf8');
let cfg = {};
try { cfg = JSON.parse(fs.readFileSync(`${dir}/agent.config.json`, 'utf8')); } catch (e) {}
const fallback = $env.DEFAULT_MODEL || 'claude-opus-4-8';
const model = (cfg.model || '').replace('${DEFAULT_MODEL}', fallback) || fallback;
const userPayload = { task: input.task || '', context: input.context || {} };
return [{ json: {
  agentId,
  model,
  maxTokens: cfg.maxTokens || 2000,
  temperature: cfg.temperature != null ? cfg.temperature : 0.7,
  system,
  user: JSON.stringify(userPayload, null, 2)
} }];

const data = $input.item.json;
const block = (data.content || [])[0] || {};
const text = block.text || '';
const cleaned = text.replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '').trim();
let parsed;
try { parsed = JSON.parse(cleaned); } catch (e) { parsed = { result: { raw: text }, parseError: String(e) }; }
return [{ json: { agentId: $('Load Agent (prompt+config)').item.json.agentId, ...parsed } }];
